param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='breakables-v1659a',[string]$Candidate='candidate-npc-combat-v1214fq',[string[]]$Sources=@('host','client'),[string]$Target='esc_env_cupboard_01_glass_15')
# 1659 (#132): a breakable broken in one world is broken in the other. Under the product controller the source stands
# by the lab cupboard glass and attacks it with the sword; both worlds' steps of the target (probe --breakables) and both
