$Sources=@($Sources|ForEach-Object {$_-split','})
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$lab="$root/outputs/d2-coop-lab";$out=Join-Path $PSScriptRoot $Take
$mutex=[Threading.Mutex]::new($false,'Local\D2CoopLab_NativeOperation_01a11a65');$owned=$false;$dirty=$false;$failure=$null
$pids=@{};$inventory=@{};$rows=[Collections.Generic.List[object]]::new();$inv=[Globalization.CultureInfo]::InvariantCulture
function Save($p,$v){$v|ConvertTo-Json -Depth 15|Set-Content -LiteralPath $p}
function C($r,$cmd){& "$lab/Send-D2Command.ps1" -Role $r -Command $cmd -WaitConsumed -ReceiptTimeoutMs 8000|Out-Null}
function I($r,$b='Neutral',$ms=100){& "$lab/Send-D2Input.ps1" -Role $r -Button $b -DurationMs $ms|Out-Null}
function S($r,$suffix=''){for($a=0;$a-lt40;$a++){try{return(Get-Content "$root/work/lab-instances/$r/coop-status.json$suffix" -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)}catch{Start-Sleep -Milliseconds 25}};throw "Status unavailable $r"}
function Q($r,$mode,$arg=0){for($a=0;$a-lt8;$a++){$raw=if($arg){& "$lab/bin/d2_runtime_probe.exe" $pids[$r] $mode $arg}else{& "$lab/bin/d2_runtime_probe.exe" $pids[$r] $mode};if(!$LASTEXITCODE){return($raw|ConvertFrom-Json)};Start-Sleep -Milliseconds 20};throw "Native read failed $mode"}
function F($v){([double]$v).ToString('F5',$inv)}
function Guard($r){$g=@((Q $r '--world-npcs').npcs|Where-Object {$_.spawnerName-eq'ld_spawner_guard_tutorial_2'-and$_.unique-and$_.reciprocal-and$_.definition-eq'models/characters/def/generic/dunwall_guard_male_small_01.def'});if($g.Count-ne1){throw "Exact upper-floor guard2 absent ($r)"};$g[0]}
function Live($r){$s=S $r;$m=S $r '.movement.json';$x=S $r '.shadow-stream.json';$a=$s.probeRenderPosition;$b=$s.remotePosition
 $d=if($a-and$b){[Math]::Sqrt(($a[0]-$b[0])*($a[0]-$b[0])+($a[1]-$b[1])*($a[1]-$b[1])+($a[2]-$b[2])*($a[2]-$b[2]))}else{999}
 @{follow=$s.probeFollowEnabled;distance=[Math]::Round($d,3);product=(S $r '.product.json').result;bank=[bool]$m.active;stream=[bool]($x.armed-and$x.ready);ok=($s.probeActorHandle-and$s.probeFollowEnabled-and$d-lt1.0-and$m.active-and$x.armed-and$x.ready-and$s.remoteFresh)}}
function WaitLive($tag,$limit=30000){$w=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 300;$p=@{host=(Live host);client=(Live client)};$ok=$p.host.ok-and$p.client.ok}while(!$ok-and$w.ElapsedMilliseconds-lt$limit);$p.ok=$ok;$p.waitMs=$w.ElapsedMilliseconds;Save "$out/live-$tag.json" $p;$p}
function Arm{foreach($r in 'host','client'){I $r;C $r 'coop_movement_fixture off';C $r 'coop_product_auto on'}
 $w=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 500;$ok=(S host '.product.json').result-eq'armed'-and(S client '.product.json').result-eq'armed'}while(!$ok-and$w.ElapsedMilliseconds-lt60000)
 if(!$ok){throw 'Product controller not armed'}}
function Disarm{$cw=[Diagnostics.Stopwatch]::StartNew();try{C host 'coop_npc_combat fixture_off'}catch{}
 do{$off=$true;foreach($r in 'host','client'){try{I $r;C $r 'coop_player_health_hold off';C $r 'coop_observer_camera off';C $r 'coop_product_auto off';C $r 'coop_movement_resume off';foreach($cmd in 'coop_breakable_sync off','coop_usable_sync off','coop_door_sync off','coop_coin_sync off','coop_npc_stream off','coop_shadow_stream off','coop_movement_bank off','coop_trigger_mirror off'){C $r $cmd};C $r 'coop_checkpoint_sync off'
   if((S $r '.reset.json').enabled){$off=$false;$st=S $r;if($st.localGameLogicState-in8,15){I $r A 300}elseif($st.localGameLogicState-eq2){I $r B 200}}}catch{}}
  if(!$off){Start-Sleep -Milliseconds 1500}}while(!$off-and$cw.ElapsedMilliseconds-lt60000)
 foreach($r in 'host','client'){try{if((S $r).localGameLogicState-in2,12){I $r B 200;Start-Sleep -Milliseconds 800}}catch{}}}
function Restore($tag){Disarm
 & "$root/work/PrepareShadowSword.ps1" *>> "$out/checkpoint-restore.log"
 & "$PSScriptRoot/Restore-LabNoteInventory-v779.ps1" -Baseline "$PSScriptRoot/native-coin-reward-v786c" -Evidence "$out/note-restoration-$tag" *>> "$out/note-restoration.log"
 foreach($r in 'host','client'){$restored=Q $r '--player-inventory'
  if(Compare-Object @($inventory[$r].items|ForEach-Object {"$($_.name):$($_.quantity)"}) @($restored.items|ForEach-Object {"$($_.name):$($_.quantity)"})){throw "Checkpoint inventory differs ($r)"}
  if((Q $r '--health' 1).current-ne56){throw "Restored player health differs ($r)"}}}
function Brk($r,$name){$b=@((Q $r '--breakables').breakables|Where-Object {$_.name-eq$name});if($b.Count-ne1){return $null};$b[0]}
try{
 try{$owned=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$owned=$true};if(!$owned){throw 'Another native operation remains active'}
 if(Test-Path -LiteralPath $out){throw 'Unique evidence take required'};New-Item -ItemType Directory $out|Out-Null;Copy-Item $PSCommandPath "$out/run-script.ps1"
 [ordered]@{pid=$PID;operation='Breakables1659';take=$Take;started=(Get-Date).ToString('o');state='running'}|ConvertTo-Json|Set-Content "$root/work/movement-integration/native-operation-owner.json"
 $pin=Get-Content "$root/work/movement-integration/$Candidate/identity.json" -Raw|ConvertFrom-Json;$dll=(Get-FileHash "$root/work/asset-game/dinput8.dll").Hash;if($dll-ne$pin.dll){throw "Expected $Candidate"}
 foreach($r in 'host','client'){
  $l=Get-Content "$root/work/lab-instances/$r/launch.json" -Raw|ConvertFrom-Json
  if(!$l.assetExperiment-or(Get-Process -Id $l.pid).Path-ne(Join-Path $root 'work/asset-game/Dishonored2.exe')){throw 'Wrong isolated game'};$pids[$r]=$l.pid;I $r
  if((S $r).localGameLogicState-ne1){throw "$r not in gameplay"}
  $inventory[$r]=Q $r '--player-inventory';Save "$out/inventory-before-$r.json" $inventory[$r]
 }
 Save "$out/identity.json" ([ordered]@{candidate=$Candidate;dll=$dll;probe=(Get-FileHash "$lab/bin/d2_runtime_probe.exe").Hash;sources=$Sources})
 foreach($source in $Sources){
  $peer=if($source-eq'host'){'client'}else{'host'};$key="$source-sword"
  $row=[ordered]@{source=$source;case='sword';target=$Target;observer=$peer;passed=$false;failure=$null;checks=[Collections.Generic.List[string]]::new()}
  $captures=@()
  try{
   $dirty=$true;Arm
   foreach($q in 'host','client'){C $q 'setviewpos -33 -153 68.1 90 0'}
   $live=WaitLive "$key-armed" 45000;if(!$live.ok){throw 'Partner presentation not live after arming'}
   $bw=[Diagnostics.Stopwatch]::StartNew()
   do{Start-Sleep -Milliseconds 400;$bs=[ordered]@{host=(S host '.breakable-sync.json');client=(S client '.breakable-sync.json')}}while(!($bs.host.result-eq'active'-and$bs.client.result-eq'active'-and$bs.host.catalog-gt0-and$bs.client.catalog-gt0)-and$bw.ElapsedMilliseconds-lt20000)
   Save "$out/$key-sync-armed.json" $bs
   if(!($bs.host.result-eq'active'-and$bs.client.result-eq'active')){throw "Breakable sync not active: host $($bs.host.result), client $($bs.client.result)"}
   $row.catalog=[ordered]@{host=$bs.host.catalog;client=$bs.client.catalog};$row.checks.Add("Breakable catalogs: host $($bs.host.catalog), client $($bs.client.catalog)")
   $before=[ordered]@{host=(Brk host $Target);client=(Brk client $Target)};$row.before=$before
   if(!$before.host-or!$before.client){throw "Target $Target not in both worlds"};if($before.host.step-or$before.client.step){throw 'Target already broken'}
   $tp=$before.host.position;$tx=[double]$tp[0];$ty=[double]$tp[1]
   # The source 1.4 m north of the glass, facing it and looking slightly down; the peer's camera held 2.6 m to the side.
   C $source ('setviewpos {0} {1} 68.1 -90 0' -f (F $tx),(F ($ty+1.4)));Start-Sleep -Milliseconds 500
   try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 12 -Quick|Out-Null}catch{}
   $cx=$tx-2.2;$cy=$ty+1.6;$cyaw=[Math]::Atan2($ty-$cy,$tx-$cx)*180/[Math]::PI
   try{$op=(Q $peer '--player-states').position;C $peer ('setviewpos {0} {1} {2} {3} 0' -f (F $op[0]),(F $op[1]),(F ([double]$op[2]+1.7)),(F $cyaw));Start-Sleep -Milliseconds 300
    & "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $peer -Pitch 12 -Quick|Out-Null
    C $peer ('coop_observer_camera hold_at {0} {1} 68.2' -f (F $cx),(F $cy));Start-Sleep -Milliseconds 300;$row.cameraHeld=(S $peer '.observer-camera.json').active}catch{$row.cameraError=$_.Exception.Message}
   foreach($pair in @(@($source,'source'),@($peer,'observer'))){$hwnd=(Get-Process -Id $pids[$pair[0]]).MainWindowHandle.ToInt64()
    $captures+=Start-Process (Get-Command ffmpeg).Source -ArgumentList @('-hide_banner','-loglevel','warning','-nostdin','-f','lavfi','-i',"gfxcapture=hwnd=${hwnd}:capture_cursor=0:max_framerate=30:width=-2:height=-2,hwdownload,format=bgra",'-t','11','-an','-c:v','libx264','-preset','veryfast','-crf','18','-pix_fmt','yuv420p','-fps_mode','passthrough','-movflags','+faststart',"$out/$key-$($pair[1]).mp4") -WindowStyle Hidden -RedirectStandardError "$out/$key-$($pair[1])-capture.log" -RedirectStandardOutput "$out/$key-$($pair[1])-capture.stdout" -PassThru}
   Start-Sleep -Milliseconds 800
   $series=[Collections.Generic.List[object]]::new();$w=[Diagnostics.Stopwatch]::StartNew();$presses=0;$sourceAt=$null;$peerAt=$null
   while($w.ElapsedMilliseconds-lt7000){
    if($presses-lt3-and!$sourceAt-and$w.ElapsedMilliseconds-ge$presses*900){& "$lab/Send-D2Input.ps1" -Role $source -RightTrigger 255 -DurationMs 250|Out-Null;$presses++}
    $sb=Brk $source $Target;$pb=Brk $peer $Target
    if($sb-and$sb.step-ge1-and$null-eq$sourceAt){$sourceAt=$w.ElapsedMilliseconds};if($pb-and$pb.step-ge1-and$null-eq$peerAt){$peerAt=$w.ElapsedMilliseconds}
    $series.Add([pscustomobject]@{ms=$w.ElapsedMilliseconds;presses=$presses;source=$sb;observer=$pb})
    if($sourceAt-and$peerAt-and$w.ElapsedMilliseconds-$peerAt-ge2500){break}
    Start-Sleep -Milliseconds 150}
   foreach($c in $captures){if(!$c.WaitForExit(30000)){Stop-Process -Id $c.Id}};$captures=@()
   try{C $peer 'coop_observer_camera off'}catch{}
   Save "$out/$key-series.json" @($series)
   foreach($q in 'host','client'){try{Copy-Item -LiteralPath "$root/work/lab-instances/$q/coop-status.json.breakable-sync.json" -Destination "$out/$key-$q.breakable-sync.json" -ErrorAction Stop}catch{}}
   $row.presses=$presses;$row.sourceBrokeAtMs=$sourceAt;$row.peerBrokeAtMs=$peerAt
   $row.after=[ordered]@{source=(Brk $source $Target);observer=(Brk $peer $Target)}
   $row.allBroken=[ordered]@{source=@((Q $source '--breakables').breakables|Where-Object {$_.step-gt0}|ForEach-Object {"$($_.name):$($_.step)"});observer=@((Q $peer '--breakables').breakables|Where-Object {$_.step-gt0}|ForEach-Object {"$($_.name):$($_.step)"})}
   if($null-eq$sourceAt){throw 'The sword did not break the target in the source world'};$row.checks.Add("Source broke $Target at $sourceAt ms ($presses presses)")
   if($null-eq$peerAt){throw 'The target stayed whole in the peer world'};$row.checks.Add("Peer world broke it at $peerAt ms ($([int]$peerAt-[int]$sourceAt) ms after the source)")
   $diff=Compare-Object @($row.allBroken.source) @($row.allBroken.observer);if($diff){$row.brokenDiff=@($diff|ForEach-Object {"$($_.SideIndicator)$($_.InputObject)"});throw "Broken sets differ: $($row.brokenDiff-join ', ')"}
   $row.checks.Add("Same broken set in both worlds: $(@($row.allBroken.source)-join ', ')")
   $row.passed=$true
  }catch{$row.failure=$_.Exception.Message}
  foreach($c in $captures){if($c){try{if(!$c.HasExited){Stop-Process -Id $c.Id}}catch{}}}
  try{Restore $key;$row.restored=$true}catch{$row.restored=$false;$row.failure=(("$($row.failure); restore: "+$_.Exception.Message)).TrimStart('; ')}
  $rows.Add([pscustomobject]$row);Save "$out/$key.json" ([pscustomobject]$row)
  if(!$row.restored){throw "Fixture restore failed after $key"}
 }
 $dirty=$false
}catch{$failure=$_.Exception.Message;Save "$out/failure.json" @{message=$failure;stack=$_.ScriptStackTrace}}finally{
 if($owned){
  if($dirty){try{Restore 'final'}catch{$failure=($failure+'; restore: '+$_.Exception.Message).TrimStart('; ')}}else{Disarm}
  $errors=[Collections.Generic.List[string]]::new()
  try{foreach($f in(Get-Content "$root/work/movement-integration/protected-save-hashes-before-v4.json" -Raw|ConvertFrom-Json)){if((Get-FileHash $f.Path).Hash-ne$f.Hash){$errors.Add('Protected file changed')}}}catch{$errors.Add($_.Exception.Message)}
  foreach($r in 'host','client'){try{$s=S $r;if($s.localGameLogicState-ne1-or!$s.remoteFresh-or(Q $r '--health' 1).current-ne56){$errors.Add("$r gameplay/transport/health not restored")}}catch{$errors.Add("$r status unavailable")}}
  if(Test-Path -LiteralPath $out){
   Save "$out/restoration.json" @{passed=(!$errors.Count);errors=@($errors)}
   $bad=@($rows|Where-Object {!$_.passed});if(!$failure-and$bad.Count){$failure="$($bad.Count) case(s) failed: "+(($bad|ForEach-Object {"$($_.source)-$($_.case): $($_.failure)"})-join ' | ')}
   if($errors.Count-and!$failure){$failure=$errors-join '; '}
   Save "$out/result.json" ([ordered]@{passed=(!$failure);failure=$failure;cases=@($rows);scope='Stage 4 breakables (#132): the source breaks the lab cupboard glass with the sword under the product controller; the glass must break in the peer world too and both worlds must end with the same broken set; fixture restored after every case.'})
  }
  [ordered]@{pid=$PID;operation='Breakables1659';take=$Take;ended=(Get-Date).ToString('o');state='finished'}|ConvertTo-Json|Set-Content "$root/work/movement-integration/native-operation-owner.json"
  $mutex.ReleaseMutex()
 };$mutex.Dispose()
}
if($failure){throw $failure};"PASS_BREAKABLES $($rows.Count) cases"
